mapper.select:
WITH base AS ( SELECT DISTINCT t.item_id FROM stock_transaction t WHERE (#{q.toDate}::date IS NULL OR t.created_at < #{q.toDate}::date + INTERVAL '1 day')
), opening AS ( SELECT x.item_id AS item_id, SUM(x.after_qty) AS opening_qty FROM ( SELECT t.item_id, t.after_qty, row_number() OVER (PARTITION BY t.item_id, t.warehouse_id, t.batch_id, t.location_id ORDER BY t.created_at DESC) AS rn FROM stock_transaction t WHERE t.created_at < #{q.fromDate}
) x WHERE x.rn = 1 GROUP BY x.item_id ), closing AS ( SELECT x.item_id AS item_id, SUM(x.after_qty) AS closing_qty FROM ( SELECT t.item_id, t.after_qty, row_number() OVER (PARTITION BY t.item_id, t.warehouse_id, t.batch_id, t.location_id ORDER BY t.created_at DESC) AS rn FROM stock_transaction t WHERE (#{q.toDate}::date IS NULL OR t.created_at < #{q.toDate}::date + INTERVAL '1 day')
) x WHERE x.rn = 1 GROUP BY x.item_id ), inflow AS ( SELECT t.item_id AS item_id, SUM(t.change_qty) AS in_qty FROM stock_transaction t WHERE t.biz_code IN ('inbound', 'transfer_in', 'adjust_in') AND (#{q.fromDate}::date IS NULL OR t.created_at >= #{q.fromDate}) AND (#{q.toDate}::date IS NULL OR t.created_at < #{q.toDate}::date + INTERVAL '1 day')
GROUP BY t.item_id ), outflow AS ( SELECT t.item_id AS item_id, -SUM(t.change_qty) AS out_qty FROM stock_transaction t WHERE t.biz_code IN ('outbound', 'transfer_out', 'adjust_out') AND (#{q.fromDate}::date IS NULL OR t.created_at >= #{q.fromDate}) AND (#{q.toDate}::date IS NULL OR t.created_at < #{q.toDate}::date + INTERVAL '1 day')
GROUP BY t.item_id ), in_amount AS ( SELECT i.item_id AS item_id, SUM(i.tax_inclusive_total) AS in_amount FROM inbound_doc_item i JOIN inbound_doc d ON d.id = i.doc_id WHERE d.status = 'finished' AND (#{q.fromDate}::date IS NULL OR d.doc_date >= #{q.fromDate}) AND (#{q.toDate}::date IS NULL OR d.doc_date <= #{q.toDate}) AND EXISTS (SELECT 1 FROM stock_transaction x WHERE x.doc_no = d.doc_no)
GROUP BY i.item_id ), out_amount AS ( SELECT i.item_id AS item_id, SUM(i.tax_inclusive_total) AS out_amount FROM outbound_doc_item i JOIN outbound_doc d ON d.id = i.doc_id WHERE d.status = 'finished' AND (#{q.fromDate}::date IS NULL OR d.doc_date >= #{q.fromDate}) AND (#{q.toDate}::date IS NULL OR d.doc_date <= #{q.toDate}) AND EXISTS (SELECT 1 FROM stock_transaction x WHERE x.doc_no = d.doc_no)
GROUP BY i.item_id ) SELECT b.item_id AS "itemId", COALESCE(o.opening_qty, 0) AS "openingQty", COALESCE(c.closing_qty, 0) AS "closingQty", COALESCE(f.in_qty, 0) AS "inQty", COALESCE(ot.out_qty, 0) AS "outQty", ia.in_amount AS "inAmount", oa.out_amount AS "outAmount" FROM base b LEFT JOIN opening o ON o.item_id = b.item_id LEFT JOIN closing c ON c.item_id = b.item_id LEFT JOIN inflow f ON f.item_id = b.item_id LEFT JOIN outflow ot ON ot.item_id = b.item_id LEFT JOIN in_amount ia ON ia.item_id = b.item_id LEFT JOIN out_amount oa ON oa.item_id = b.item_id ORDER BY b.item_id LIMIT #{q.limit} OFFSET #{q.offset}

SELECT x.item_id AS "itemId", x.warehouse_id AS "warehouseId", SUM(x.after_qty) AS "qty" FROM ( SELECT t.item_id, t.warehouse_id, t.after_qty, row_number() OVER (PARTITION BY t.item_id, t.warehouse_id, t.batch_id, t.location_id ORDER BY t.created_at DESC) AS rn FROM stock_transaction t WHERE t.item_id IN
#{it}
AND (#{q.toDate}::date IS NULL OR t.created_at < #{q.toDate}::date + INTERVAL '1 day')
AND t.warehouse_id = #{q.warehouseId}
AND t.warehouse_id IN
#{wh}
) x WHERE x.rn = 1 GROUP BY x.item_id, x.warehouse_id

mapper.sql:
SELECT s.warehouse_id, s.item_id, s.batch_id, SUM(s.quantity) AS qty
FROM stock s
WHERE s.quantity > 0

    AND s.warehouse_id = #{q.warehouseId}


    AND s.warehouse_id IN

        #{wh}



    AND s.item_id IN

        #{it}


GROUP BY s.warehouse_id, s.item_id, s.batch_id

WITH po AS ( SELECT po.supplier_id AS supplier_id, COUNT(DISTINCT po.id) AS order_count, COALESCE(SUM(poi.ordered_qty), 0) AS order_qty, COALESCE(SUM(poi.tax_inclusive_total), 0) AS order_amount FROM purchase_order po JOIN purchase_order_item poi ON poi.order_id = po.id WHERE po.status <> 'voided' AND (#{q.fromDate}::date IS NULL OR po.doc_date >= #{q.fromDate}) AND (#{q.toDate}::date IS NULL OR po.doc_date <= #{q.toDate})
AND po.supplier_id = #{q.supplierId}
AND EXISTS (SELECT 1 FROM inbound_doc d WHERE d.ref_type = 'purchase' AND d.ref_doc_id = po.id AND d.warehouse_id IN #{wh})
GROUP BY po.supplier_id ), ret AS ( SELECT po.supplier_id AS supplier_id, COALESCE(SUM(pri.quantity), 0) AS return_qty, COALESCE(SUM(pri.tax_inclusive_total), 0) AS return_amount FROM purchase_return pr JOIN purchase_return_item pri ON pri.doc_id = pr.id JOIN purchase_order po ON po.id = pr.purchase_order_id WHERE (#{q.fromDate}::date IS NULL OR pr.doc_date >= #{q.fromDate}) AND (#{q.toDate}::date IS NULL OR pr.doc_date <= #{q.toDate})
AND po.supplier_id = #{q.supplierId}
AND pr.warehouse_id IN
#{wh}
GROUP BY po.supplier_id ), base AS ( SELECT supplier_id FROM po UNION SELECT supplier_id FROM ret )

mapper.select:
SELECT po.supplier_id AS "partyId", po.doc_no AS "docNo", po.doc_date AS "docDate", 'purchase' AS "docType", COALESCE(SUM(poi.tax_inclusive_total), 0) AS "amount" FROM purchase_order po JOIN purchase_order_item poi ON poi.order_id = po.id WHERE po.status <> 'voided' AND (#{q.fromDate}::date IS NULL OR po.doc_date >= #{q.fromDate}) AND (#{q.toDate}::date IS NULL OR po.doc_date <= #{q.toDate}) AND po.supplier_id IN #{p}
AND EXISTS (SELECT 1 FROM inbound_doc d WHERE d.ref_type = 'purchase' AND d.ref_doc_id = po.id AND d.warehouse_id IN #{wh})
GROUP BY po.supplier_id, po.doc_no, po.doc_date UNION ALL SELECT po.supplier_id AS "partyId", pr.doc_no AS "docNo", pr.doc_date AS "docDate", 'purchase_return' AS "docType", COALESCE(SUM(pri.tax_inclusive_total), 0) AS "amount" FROM purchase_return pr JOIN purchase_order po ON po.id = pr.purchase_order_id LEFT JOIN purchase_return_item pri ON pri.doc_id = pr.id WHERE (#{q.fromDate}::date IS NULL OR pr.doc_date >= #{q.fromDate}) AND (#{q.toDate}::date IS NULL OR pr.doc_date <= #{q.toDate}) AND po.supplier_id IN #{p}
AND pr.warehouse_id IN
#{wh}
GROUP BY po.supplier_id, pr.doc_no, pr.doc_date ORDER BY 3, 2

mapper.sql:
WITH so AS ( SELECT so.customer_id AS customer_id, COUNT(DISTINCT so.id) AS order_count, COALESCE(SUM(soi.ordered_qty), 0) AS order_qty, COALESCE(SUM(soi.tax_inclusive_total), 0) AS order_amount FROM sales_order so JOIN sales_order_item soi ON soi.order_id = so.id WHERE so.status <> 'voided' AND (#{q.fromDate}::date IS NULL OR so.doc_date >= #{q.fromDate}) AND (#{q.toDate}::date IS NULL OR so.doc_date <= #{q.toDate})
AND so.customer_id = #{q.customerId}
AND so.warehouse_id IN
#{wh}
GROUP BY so.customer_id ), ret AS ( SELECT so.customer_id AS customer_id, COALESCE(SUM(sri.quantity), 0) AS return_qty, COALESCE(SUM(sri.tax_inclusive_total), 0) AS return_amount FROM sales_return sr JOIN sales_return_item sri ON sri.doc_id = sr.id JOIN sales_order so ON so.id = sr.sales_order_id WHERE (#{q.fromDate}::date IS NULL OR sr.doc_date >= #{q.fromDate}) AND (#{q.toDate}::date IS NULL OR sr.doc_date <= #{q.toDate})
AND so.customer_id = #{q.customerId}
AND sr.warehouse_id IN
#{wh}
GROUP BY so.customer_id ), base AS ( SELECT customer_id FROM so UNION SELECT customer_id FROM ret )

mapper.select:
SELECT so.customer_id AS "partyId", so.doc_no AS "docNo", so.doc_date AS "docDate", 'sales' AS "docType", COALESCE(SUM(soi.tax_inclusive_total), 0) AS "amount" FROM sales_order so JOIN sales_order_item soi ON soi.order_id = so.id WHERE so.status <> 'voided' AND (#{q.fromDate}::date IS NULL OR so.doc_date >= #{q.fromDate}) AND (#{q.toDate}::date IS NULL OR so.doc_date <= #{q.toDate}) AND so.customer_id IN #{p}
AND so.warehouse_id IN
#{wh}
GROUP BY so.customer_id, so.doc_no, so.doc_date UNION ALL SELECT so.customer_id AS "partyId", sr.doc_no AS "docNo", sr.doc_date AS "docDate", 'sales_return' AS "docType", COALESCE(SUM(sri.tax_inclusive_total), 0) AS "amount" FROM sales_return sr JOIN sales_order so ON so.id = sr.sales_order_id LEFT JOIN sales_return_item sri ON sri.doc_id = sr.id WHERE (#{q.fromDate}::date IS NULL OR sr.doc_date >= #{q.fromDate}) AND (#{q.toDate}::date IS NULL OR sr.doc_date <= #{q.toDate}) AND so.customer_id IN #{p}
AND sr.warehouse_id IN
#{wh}
GROUP BY so.customer_id, sr.doc_no, sr.doc_date ORDER BY 3, 2
